schema.shape_profile:
@prefix bioschemas_draft: <https://bioschemas.org/draft_terms/> .
@prefix dash: <http://datashapes.org/dash#> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix form: <https://platform.vhp4safety.nl/model/v1/form#> .
@prefix glossary: <https://vhp4safety.github.io/glossary#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

form:Dataset a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:message "A dataset needs one title." ;
            sh:minCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:name "Authors" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 3 ;
            sh:path schema:creator ],
        [ sh:datatype xsd:date ;
            sh:maxCount 1 ;
            sh:name "Published" ;
            sh:order 4 ;
            sh:path schema:datePublished ],
        [ sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:message "Choose the steps from the list; other values are kept, but the data catalogue's filters do not show them." ;
            sh:name "Assessment steps" ;
            sh:order 5 ;
            sh:path glossary:VHP0000152 ;
            sh:severity sh:Warning ],
        [ sh:class schema:Question ;
            sh:name "Case-study questions" ;
            sh:node form:Question ;
            sh:order 6 ;
            sh:path glossary:VHP0000151 ],
        [ sh:description "Terms that say what the data is about, such as the organism." ;
            sh:message "Give a topic as the web address of a term." ;
            sh:name "Topics" ;
            sh:nodeKind sh:IRI ;
            sh:order 7 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:class bioschemas_draft:LabProtocol ;
            sh:description "The methods of the platform with which the data was measured." ;
            sh:name "Methods" ;
            sh:node form:LabProtocol ;
            sh:order 8 ;
            sh:path schema:measurementTechnique ],
        [ sh:class schema:ScholarlyArticle ;
            sh:name "Publications" ;
            sh:node form:ScholarlyArticle ;
            sh:order 9 ;
            sh:path schema:citation ],
        [ sh:maxCount 1 ;
            sh:message "Give the license as a web address." ;
            sh:name "License" ;
            sh:nodeKind sh:IRI ;
            sh:order 10 ;
            sh:path schema:license ;
            sh:severity sh:Warning ],
        [ sh:description "The dataset's page in BioStudies or Zenodo." ;
            sh:maxCount 1 ;
            sh:name "Address" ;
            sh:nodeKind sh:IRI ;
            sh:order 11 ;
            sh:path schema:url ],
        [ sh:name "DOI and other addresses" ;
            sh:nodeKind sh:IRI ;
            sh:order 12 ;
            sh:path schema:sameAs ],
        [ sh:datatype xsd:string ;
            sh:name "Keywords" ;
            sh:order 13 ;
            sh:path schema:keywords ] ;
    sh:targetClass schema:Dataset .

form:ResearchProject a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:group form:casestudy ;
            sh:maxCount 1 ;
            sh:message "A case study needs one name." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:description "What the case study studies, in one sentence." ;
            sh:group form:casestudy ;
            sh:maxCount 1 ;
            sh:name "Aim" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:description "The medical condition that the case study is about, as a SNOMED or MONDO term." ;
            sh:group form:casestudy ;
            sh:name "Condition" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:about ],
        [ sh:datatype xsd:string ;
            sh:group form:casestudy ;
            sh:name "Keywords" ;
            sh:order 4 ;
            sh:path schema:keywords ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:group form:casestudy ;
            sh:maxCount 1 ;
            sh:name "Introduction to the questions" ;
            sh:order 5 ;
            sh:path schema:abstract ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:description "The text of the case study's page, in HTML, when it is not in sections." ;
            sh:group form:casestudy ;
            sh:maxCount 1 ;
            sh:name "Text" ;
            sh:order 6 ;
            sh:path schema:text ],
        [ sh:class schema:WebPageElement ;
            sh:description "The sections of the case study's page, each with a heading, a text in HTML, and its position." ;
            sh:group form:parts ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 1 ;
            sh:path schema:hasPart ],
        [ sh:class schema:Question ;
            sh:description "The regulatory questions of the case study, each at /casestudies/<case>/<question>, with the process flow steps of its workflow." ;
            sh:group form:parts ;
            sh:name "Regulatory questions" ;
            sh:node form:Question ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path glossary:VHP0000151 ] ;
    sh:targetClass schema:ResearchProject .

form:SoftwareApplication a sh:NodeShape ;
    rdfs:comment "Tools state the Bioschemas profile they follow (ComputationalTool)." ;
    sh:property [ sh:datatype xsd:string ;
            sh:description "The tool's name as its developers write it." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "Give the tool one name." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:class schema:Question ;
            sh:description "The regulatory questions of the case studies that the tool helps to answer (the glossary's Regulatory Question). The tool catalogue filters tools by them." ;
            sh:group form:about ;
            sh:name "Case-study questions" ;
            sh:node form:Question ;
            sh:order 7 ;
            sh:path glossary:VHP0000151 ],
        [ sh:description "Terms of the VHP4Safety glossary that say what the tool deals with, such as Model or Adverse Outcome Pathway." ;
            sh:group form:about ;
            sh:message "Give a topic as the web address of a term, such as https://vhp4safety.github.io/glossary#VHP0000055 (Model)." ;
            sh:name "Topics" ;
            sh:nodeKind sh:IRI ;
            sh:order 8 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:description "The organisations that offer the tool. VHP4Safety is one of them when the tool runs on the platform's own servers; its page then says that VHP4Safety hosts it." ;
            sh:group form:people ;
            sh:name "Provided by" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 1 ;
            sh:path schema:provider ],
        [ sh:description "The organisations that developed the tool. Choose VHP4Safety when the project developed it." ;
            sh:group form:people ;
            sh:name "Developed by" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 2 ;
            sh:path schema:creator ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:description "What the tool does and what it is used for, in two or three sentences. It is shown in the tool catalogue and on the tool's page." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "Describe the tool in a few sentences." ;
            sh:minCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:description "The people to contact about the tool. Their names and email addresses are shown on the tool's support tab." ;
            sh:group form:people ;
            sh:name "Contact people" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 3 ;
            sh:path schema:maintainer ],
        [ sh:class schema:WebPage ;
            sh:description "Pages that explain the tool or show it at work: introductions, tutorials, demos and deployment guides, each with its title." ;
            sh:group form:documentation ;
            sh:name "Guides and demos" ;
            sh:node form:WebPage ;
            sh:nodeKind sh:BlankNode ;
            sh:order 1 ;
            sh:path schema:softwareHelp ],
        [ sh:description "The tool's website or documentation." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:message "A website helps people find the tool; add it when the tool has one." ;
            sh:minCount 1 ;
            sh:name "Website" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ;
            sh:severity sh:Warning ],
        [ sh:class schema:WebPage ;
            sh:description "The VHP4Safety workflows and tutorials that use the tool, each with its title." ;
            sh:group form:documentation ;
            sh:name "Used in workflows" ;
            sh:node form:WebPage ;
            sh:nodeKind sh:BlankNode ;
            sh:order 2 ;
            sh:path schema:subjectOf ],
        [ sh:class schema:VideoObject ;
            sh:description "Videos about the tool that can be embedded on its page, such as PeerTube videos, each with its title." ;
            sh:group form:documentation ;
            sh:name "Videos" ;
            sh:node form:VideoObject ;
            sh:nodeKind sh:BlankNode ;
            sh:order 3 ;
            sh:path schema:video ],
        [ sh:class schema:ScholarlyArticle ;
            sh:description "The publication to cite when the tool is used, such as the article that describes it. Its page on the platform links to its DOI." ;
            sh:group form:documentation ;
            sh:maxCount 1 ;
            sh:name "Publication to cite" ;
            sh:node form:ScholarlyArticle ;
            sh:order 4 ;
            sh:path schema:citation ],
        [ sh:datatype xsd:string ;
            sh:description "The words that find training material about the tool on ELIXIR TeSS and Taxila. The tool's page shows what they find." ;
            sh:group form:documentation ;
            sh:maxCount 1 ;
            sh:name "Training search term" ;
            sh:order 5 ;
            sh:path schema:keywords ],
        [ sh:datatype xsd:string ;
            sh:description "The version of the tool that the platform describes, as its developers number it." ;
            sh:group form:technical ;
            sh:maxCount 1 ;
            sh:name "Version" ;
            sh:order 1 ;
            sh:path schema:softwareVersion ],
        [ sh:description "The license under which the tool is shared." ;
            sh:group form:technical ;
            sh:maxCount 1 ;
            sh:message "Give the license as a web address, such as https://spdx.org/licenses/MIT." ;
            sh:name "License" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:license ;
            sh:severity sh:Warning ],
        [ sh:description "Where the tool's source code is kept, such as its GitHub repository." ;
            sh:group form:technical ;
            sh:name "Source code" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:isBasedOn ],
        [ sh:description "Where the tool can be downloaded: its container image or its software packages." ;
            sh:group form:technical ;
            sh:name "Downloads" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:downloadUrl ],
        [ sh:description "How mature the tool is, as a technology readiness level: from TRL 1 (basic principles observed) to TRL 9 (proven in its operational environment)." ;
            sh:group form:technical ;
            sh:in ( "TRL 1" "TRL 2" "TRL 3" "TRL 4" "TRL 5" "TRL 6" "TRL 7" "TRL 8" "TRL 9" ) ;
            sh:maxCount 1 ;
            sh:message "Choose a technology readiness level from TRL 1 to TRL 9." ;
            sh:name "Technology readiness" ;
            sh:order 5 ;
            sh:path schema:creativeWorkStatus ],
        [ sh:description "The address where the tool runs and can be used, when that is not its website. The tool's page links to it as \"Run the tool\"." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:name "Where to use it" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:installUrl ],
        [ sh:datatype xsd:string ;
            sh:description "The address of the tool's release notes, or a short note about its latest release." ;
            sh:group form:technical ;
            sh:maxCount 1 ;
            sh:name "Release notes" ;
            sh:order 6 ;
            sh:path schema:releaseNotes ],
        [ sh:description "Other web addresses of the tool, such as its pages on bio.tools, FAIRsharing, Wikipedia or the Research Software Directory. Its earlier addresses on the platform are kept here too, so that links to them still find it." ;
            sh:group form:elsewhere ;
            sh:name "Other addresses" ;
            sh:nodeKind sh:IRI ;
            sh:order 1 ;
            sh:path schema:sameAs ],
        [ sh:description "Shown on the tool's card in the catalogue." ;
            sh:group form:about ;
            sh:maxCount 1 ;
            sh:name "Logo or screenshot" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:image ],
        [ sh:description "Records of tools follow the ComputationalTool profile of Bioschemas, version 1.0, so that search engines and registries can read them." ;
            sh:group form:elsewhere ;
            sh:hasValue <https://bioschemas.org/profiles/ComputationalTool/1.0-RELEASE> ;
            sh:message "A tool follows the ComputationalTool profile of Bioschemas, version 1.0-RELEASE." ;
            sh:name "Bioschemas profile" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path dct:conformsTo ],
        [ sh:description "The process flow steps of the safety assessment that the tool supports (the glossary's Process Flow Step). The tool catalogue filters tools by them." ;
            sh:group form:about ;
            sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:message "Choose the steps from the list; other values are kept, but the catalogue's filters do not show them." ;
            sh:name "Assessment steps" ;
            sh:order 6 ;
            sh:path glossary:VHP0000152 ;
            sh:severity sh:Warning ] ;
    sh:targetClass schema:SoftwareApplication .

form:LabProtocol a sh:NodeShape ;
    rdfs:comment "Methods state the Bioschemas profile they follow (LabProtocol)." ;
    sh:property [ sh:datatype xsd:string ;
            sh:description "The method's name as it is known in the lab." ;
            sh:group form:method ;
            sh:maxCount 1 ;
            sh:message "A method needs one name." ;
            sh:minCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:description "What the method measures or shows, in one or two sentences." ;
            sh:group form:method ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:description "The process flow steps of the safety assessment that the method informs." ;
            sh:group form:method ;
            sh:in ( glossary:VHP0000153 glossary:VHP0000154 glossary:VHP0000155 glossary:VHP0000156 glossary:VHP0000158 ) ;
            sh:message "Choose the steps from the list; other values are kept, but the catalogue's filters do not show them." ;
            sh:name "Assessment steps" ;
            sh:order 3 ;
            sh:path glossary:VHP0000152 ;
            sh:severity sh:Warning ],
        [ sh:class schema:Question ;
            sh:description "The regulatory questions of the case studies that the method informs." ;
            sh:group form:method ;
            sh:name "Case-study questions" ;
            sh:node form:Question ;
            sh:order 4 ;
            sh:path glossary:VHP0000151 ],
        [ sh:description "The AOP-Wiki key events and adverse outcome pathways that the method measures, and terms of the glossary." ;
            sh:group form:method ;
            sh:message "Give a key event, a pathway or a topic as the web address of a term, such as https://identifiers.org/aop.events/1825." ;
            sh:name "Key events, pathways and topics" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:about ;
            sh:severity sh:Warning ],
        [ sh:description "Terms of ontologies such as OBI or BAO that say what kind of assay the method is." ;
            sh:group form:method ;
            sh:name "Kind of assay" ;
            sh:nodeKind sh:IRI ;
            sh:order 6 ;
            sh:path schema:additionalType ],
        [ sh:datatype xsd:string ;
            sh:description "The assay or kit that the method uses, as its vendor names it." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Assay" ;
            sh:order 1 ;
            sh:path bioschemas_draft:reagent ],
        [ sh:class schema:Organization ;
            sh:description "The company that sells the assay or kit." ;
            sh:group form:assay ;
            sh:name "Vendor" ;
            sh:node form:Organization ;
            sh:order 2 ;
            sh:path schema:provider ],
        [ sh:datatype xsd:string ;
            sh:description "The vendor's catalogue number of the assay or kit." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Catalogue number" ;
            sh:order 3 ;
            sh:path schema:identifier ],
        [ sh:description "The vendor's page of the assay or kit." ;
            sh:group form:assay ;
            sh:maxCount 1 ;
            sh:name "Product page" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path schema:url ],
        [ sh:description "The people who produce data with the method in VHP4Safety." ;
            sh:group form:people ;
            sh:name "Data producer" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 1 ;
            sh:path schema:creator ],
        [ sh:class schema:ScholarlyArticle ;
            sh:description "The publications that describe the method. Their pages on the platform link to their DOIs." ;
            sh:group form:documentation ;
            sh:name "Publications" ;
            sh:node form:ScholarlyArticle ;
            sh:order 1 ;
            sh:path schema:citation ],
        [ sh:description "The standard operating procedure or protocol that the lab follows." ;
            sh:group form:documentation ;
            sh:name "Standard operating procedure" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:subjectOf ],
        [ sh:description "The request in the cloud catalogue from which the method's record was made." ;
            sh:group form:elsewhere ;
            sh:name "Catalogue request" ;
            sh:nodeKind sh:IRI ;
            sh:order 1 ;
            sh:path schema:isBasedOn ],
        [ sh:group form:elsewhere ;
            sh:hasValue <https://bioschemas.org/profiles/LabProtocol/0.9-DRAFT> ;
            sh:message "A method follows the LabProtocol profile of Bioschemas, version 0.9-DRAFT." ;
            sh:name "Bioschemas profile" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path dct:conformsTo ] ;
    sh:targetClass bioschemas_draft:LabProtocol .

form:VideoObject a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:name "Address" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path schema:url ] ;
    sh:targetClass schema:VideoObject .

form:HowToItem a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Name" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:maxCount 1 ;
            sh:name "Page" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ] .

form:HowToSection a sh:NodeShape ;
    sh:property [ sh:class schema:HowToSection ;
            sh:description "The steps of this page, each a page at an address under this one." ;
            sh:group form:parts ;
            sh:name "Steps" ;
            sh:node form:HowToSection ;
            sh:nodeKind sh:IRI ;
            sh:order 1 ;
            sh:path schema:step ],
        [ sh:class schema:WebPageElement ;
            sh:description "The sections of the page, each with a heading, a text in HTML, and its position." ;
            sh:group form:parts ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:hasPart ],
        [ sh:description "The term of the glossary that the page is about: a process flow step, or a part of one." ;
            sh:group form:workflow ;
            sh:name "Glossary term" ;
            sh:nodeKind sh:IRI ;
            sh:order 5 ;
            sh:path schema:about ],
        [ sh:datatype xsd:string ;
            sh:description "\"disabled\" when the page's button is shown but cannot be opened yet." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Status" ;
            sh:order 6 ;
            sh:path schema:creativeWorkStatus ],
        [ sh:datatype xsd:integer ;
            sh:description "Where the page's button is among those of the page that holds it: 1 is the first." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Position" ;
            sh:order 7 ;
            sh:path schema:position ],
        [ sh:class schema:HowToTool ;
            sh:description "The tools and methods that the page lists, each with a name, a description, and its page on the platform." ;
            sh:group form:parts ;
            sh:name "Tools" ;
            sh:node form:HowToTool ;
            sh:nodeKind sh:BlankNode ;
            sh:order 2 ;
            sh:path schema:tool ],
        [ sh:class schema:HowToSupply ;
            sh:description "The data that the page lists, each with a name, a description, and its page on the platform." ;
            sh:group form:parts ;
            sh:name "Data" ;
            sh:node form:HowToSupply ;
            sh:nodeKind sh:BlankNode ;
            sh:order 3 ;
            sh:path schema:supply ],
        [ sh:datatype xsd:string ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:message "A page of a workflow needs one title." ;
            sh:minCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Summary" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ dash:singleLine false ;
            sh:datatype xsd:string ;
            sh:description "The text of the page, in HTML, when it is not in sections." ;
            sh:group form:workflow ;
            sh:maxCount 1 ;
            sh:name "Text" ;
            sh:order 3 ;
            sh:path schema:text ] ;
    sh:targetClass schema:HowToSection .

form:HowToSupply a sh:NodeShape ;
    sh:node form:HowToItem ;
    sh:targetClass schema:HowToSupply .

form:HowToTool a sh:NodeShape ;
    sh:node form:HowToItem ;
    sh:targetClass schema:HowToTool .

form:WebPage a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Description" ;
            sh:order 2 ;
            sh:path schema:description ],
        [ sh:maxCount 1 ;
            sh:name "Address elsewhere" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path schema:url ],
        [ sh:class schema:WebPageElement ;
            sh:description "The sections of a page of the platform, each with a heading, a text in HTML, its position and its anchor." ;
            sh:name "Sections" ;
            sh:node form:WebPageElement ;
            sh:nodeKind sh:BlankNode ;
            sh:order 4 ;
            sh:path schema:hasPart ] ;
    sh:targetClass schema:WebPage .

form:ScholarlyArticle a sh:NodeShape ;
    sh:property [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:name "Title" ;
            sh:order 1 ;
            sh:path schema:name ],
        [ sh:name "Authors" ;
            sh:or ( [ rdfs:label "Person" ;
                        sh:class schema:Person ;
                        sh:node form:Person ] [ rdfs:label "Organisation" ;
                        sh:class schema:Organization ;
                        sh:node form:Organization ] ) ;
            sh:order 2 ;
            sh:path schema:author ],
        [ sh:datatype xsd:date ;
            sh:maxCount 1 ;
            sh:name "Published" ;
            sh:order 3 ;
            sh:path schema:datePublished ],
